/* Divya Desam Yatra service worker. GENERATED by build.py from src/sw.js: edit the source, not sw.js.
   Keeps the whole app (page, Leaflet, icons, the temple photographs and the fonts) on the device so
   it opens with no network. A new build gets a new VERSION, which makes the browser install the
   new copy in the background; the page then shows "Update available, tap to refresh". */
const VERSION = '5.1-035857f992';
const CACHE = 'ddy-app-' + VERSION;
const FONT_CACHE = 'ddy-fonts-v1';
const TILE_CACHE = 'ddy-tiles-v1';
const TILE_MAX = 600;               // map tiles already viewed, kept for offline use (oldest dropped first)
const SHELL = ["./", "index.html", "manifest.webmanifest", "vendor/leaflet.js", "icons/apple-touch-icon.png", "icons/favicon-32.png", "icons/icon-192.png", "icons/icon-512.png", "icons/icon-maskable-512.png", "icons/icon.svg"];
const IMAGES = ["img/001.jpg", "img/002.jpg", "img/003.jpg", "img/004.jpg", "img/005.jpg", "img/006.jpg", "img/007.jpg", "img/008.jpg", "img/009.jpg", "img/010.jpg", "img/011.jpg", "img/012.jpg", "img/013.jpg", "img/014.jpg", "img/015.jpg", "img/016.jpg", "img/017.jpg", "img/018.jpg", "img/019.jpg", "img/020.jpg", "img/020a.jpg", "img/020b.jpg", "img/021.jpg", "img/022.jpg", "img/023.jpg", "img/024.jpg", "img/025.jpg", "img/026.jpg", "img/027.jpg", "img/028.jpg", "img/029.jpg", "img/030.jpg", "img/031.jpg", "img/032.jpg", "img/033.jpg", "img/034.jpg", "img/034a.jpg", "img/035.jpg", "img/036.jpg", "img/037.jpg", "img/038.jpg", "img/039.jpg", "img/040.jpg", "img/041.jpg", "img/042.jpg", "img/043.jpg", "img/044.jpg", "img/045.jpg", "img/046.jpg", "img/047.jpg", "img/048.jpg", "img/049.jpg", "img/050.jpg", "img/051.jpg", "img/052.jpg", "img/053.jpg", "img/054.jpg", "img/055.jpg", "img/056.jpg", "img/057.jpg", "img/058.jpg", "img/059.jpg", "img/060.jpg", "img/061.jpg", "img/062.jpg", "img/063.jpg", "img/064.jpg", "img/065.jpg", "img/066.jpg", "img/067.jpg", "img/068.jpg", "img/069.jpg", "img/070.jpg", "img/071.jpg", "img/072.jpg", "img/073.jpg", "img/074.jpg", "img/075.jpg", "img/076.jpg", "img/077.jpg", "img/078.jpg", "img/079.jpg", "img/080.jpg", "img/081.jpg", "img/082.jpg", "img/083.jpg", "img/084.jpg", "img/085.jpg", "img/086.jpg", "img/087.jpg", "img/088.jpg", "img/089.jpg", "img/090.jpg", "img/091.jpg", "img/092.jpg", "img/093.jpg", "img/094.jpg", "img/095.jpg", "img/096.jpg", "img/097.jpg", "img/098.jpg", "img/099.jpg", "img/100.jpg", "img/101.jpg", "img/102.jpg", "img/103.jpg", "img/104.jpg", "img/105.jpg", "img/106.jpg", "img/107.jpg", "img/108.jpg"];
const FONT_CSS = 'https://fonts.googleapis.com/css2?family=Marcellus&family=Mukta:wght@400;600&family=Noto+Serif+Tamil:wght@400;600&display=swap';

async function cacheFonts(){
  const cache = await caches.open(FONT_CACHE);
  const res = await fetch(FONT_CSS, {mode:'cors', credentials:'omit'});
  if(!res.ok) return;
  const css = await res.clone().text();
  await cache.put(FONT_CSS, res);
  const urls = [...new Set((css.match(/url\((https:\/\/fonts\.gstatic\.com\/[^)]+)\)/g) || []).map(u => u.slice(4, -1)))];
  await Promise.allSettled(urls.map(async u => { if(await cache.match(u)) return; const r = await fetch(u, {mode:'cors', credentials:'omit'}); if(r.ok) await cache.put(u, r); }));
}
self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(SHELL.map(u => new Request(u, {cache:'reload'})));          // must succeed
    for(let i = 0; i < IMAGES.length; i += 8)                                        // best effort; gaps fill in as photos are viewed
      await Promise.allSettled(IMAGES.slice(i, i + 8).map(u => cache.add(new Request(u, {cache:'reload'}))));
    await cacheFonts().catch(() => {});
  })());
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    const keep = [CACHE, FONT_CACHE, TILE_CACHE];
    await Promise.all((await caches.keys()).filter(k => k.startsWith('ddy-') && !keep.includes(k)).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});
self.addEventListener('message', e => { if(e.data === 'SKIP_WAITING') self.skipWaiting(); });

async function fromAppCache(req){
  const cache = await caches.open(CACHE);
  if(req.mode === 'navigate') return (await cache.match('index.html')) || fetch(req);
  const hit = await cache.match(req, {ignoreSearch:true});
  if(hit) return hit;
  const res = await fetch(req);
  if(res.ok && res.type === 'basic') cache.put(req, res.clone()).catch(() => {});
  return res;
}
async function fontStyles(req){   // serve the saved stylesheet at once, refresh it quietly
  const cache = await caches.open(FONT_CACHE);
  const hit = await cache.match(req.url);
  const fresh = fetch(req.url, {mode:'cors', credentials:'omit'}).then(r => { if(r.ok) cache.put(req.url, r.clone()); return r; });
  if(hit){ fresh.catch(() => {}); return hit; }
  return fresh;
}
async function fontFile(req){
  const cache = await caches.open(FONT_CACHE);
  const hit = await cache.match(req.url); if(hit) return hit;
  const r = await fetch(req.url, {mode:'cors', credentials:'omit'});
  if(r.ok) cache.put(req.url, r.clone()).catch(() => {});
  return r;
}
async function mapTile(req, url){
  const key = 'https://tile.openstreetmap.org' + url.pathname;   // a, b and c servers hold the same tile
  const cache = await caches.open(TILE_CACHE);
  const hit = await cache.match(key); if(hit) return hit;
  const r = await fetch(req);
  if(r.ok && r.type !== 'opaque'){
    cache.put(key, r.clone()).then(async () => { const keys = await cache.keys(); for(let i = 0; i < keys.length - TILE_MAX; i++) await cache.delete(keys[i]); }).catch(() => {});
  }
  return r;
}
self.addEventListener('fetch', e => {
  const req = e.request; if(req.method !== 'GET') return;
  const url = new URL(req.url);
  if(url.origin === self.location.origin) e.respondWith(fromAppCache(req));
  else if(url.hostname === 'fonts.googleapis.com') e.respondWith(fontStyles(req));
  else if(url.hostname === 'fonts.gstatic.com') e.respondWith(fontFile(req));
  else if(/(^|\.)tile\.openstreetmap\.org$/.test(url.hostname)) e.respondWith(mapTile(req, url));
});
